-- Replace consent_form's v1 body (plain single-column paragraphs, no logo,
-- underscore signature rules the source never used, and a silently
-- "corrected" wording drift) with a version checked directly against the
-- two retained sources: `LSLGC CONSENT FORM 2025 - Corp..docx` and
-- `LSLGC CONSENT FORM 2025 - Individual.docx` (both single-page, two-column
-- Word documents; the un-suffixed `LSLGC CONSENT FORM 2025.docx`/.pdf in the
-- same folder carries byte-identical body wording to the two suffixed
-- files, differing only in its own signature-block cruft, so it is not a
-- third variant — see docs/document-fidelity/source-registry.json's
-- lslgc-consent-form-corporate / lslgc-consent-form-individual entries).
--
-- Built only from primitives the Admin TipTap editor actually preserves
-- (table data-plain / data-align / span[data-if] / span[data-unless]); see
-- consent-form-preview.ts's header comment for the full source-vs-template
-- diff. Round-trips unchanged through the editor (see
-- tiptap-roundtrip.test.mts: consent_form_source_faithful).
--
-- Content changes vs the v1 body, each checked against both retained
-- sources directly (not silently "corrected" further):
--   - adds the top-left Loan Star wordmark (v1 had none) and reproduces the
--     source's two-column layout via a single-row, two-column data-plain
--     table (td content is inline-only in this schema, so paragraphs are
--     joined with <br/> rather than nested <p>).
--   - drops the underscore signature rule above each signature name — the
--     source uses a blank line, not a rule, above both the corporate
--     "Represented by:" name and the individual "Signature Over Printed
--     Name" line.
--   - restores the source's own "Loan Star Lending Group Corp., shall
--     keep..." comma (v1 had silently dropped it).
--   - restores the source's own unclosed parenthesis in item (d), "...
--     (whether such products are offered by LSLGC;" (v1 had silently added
--     a closing paren).
--   - [VERIFY WORDING] both sources read "...retained for a period of two
--     (5) years..."; v1 read "five (5) years". Kept as the source literally
--     reads it, flagged here for client confirmation rather than silently
--     re-corrected either way.
--   - adds a second, identically-labelled "Signature Over Printed Name"
--     line for the individual variant, gated on {{coBorrowerName}} (same
--     established merge key/convention as disclosure_statement) — the
--     Individual.docx source has two signature lines, not one.
--
-- Idempotent: it never archives or reinserts the same reviewed body.

WITH reviewed_body AS (
  SELECT $consent$
<div data-accurate data-document-footer="none">
<img class="doc-logo" src="logo.png" alt="Loan Star Lending Group Corp." width="160">
<h2 data-align="center">CONSENT FORM</h2>

<table data-plain><tbody>
<tr>
<td>I/we {{borrowerName}}, grant my/our free, voluntary and unconditional consent to the Processing, Verification, Collection and Remedial department of all Personal Data (as defined below), and account or transaction information or records (collectively, the &ldquo;Information&rdquo;) relating to me/us disclosed/transmitted by me/us in person or by my/our authorized agent/representative/s to the information database system of the Loan Star Lending Group Corp. (LSLGC) and/or any of its authorized agent/s or representative/s as Information controller, by whatever means in accordance with Republic Act (R.A.) 10173, otherwise known as the &ldquo;Data Privacy Act of 2012&rdquo; of the Republic of the Philippines, including its Implementing Rules and Regulations (IRR) as well as all other guidelines and issuances by the National Privacy Commission (NPC).<br/>I/we understand that my/our &ldquo;Personal Data&rdquo; means any information, whether recorded in a material form or not, (a) from which the identity of an individual is apparent or can be reasonably and directly ascertained by the entity holding the information, or when put together with other information would directly and certainly identify an individual, (b) about an individual&rsquo;s race, ethnic origin, marital status, age, color, gender, health, education and religious and/or political affiliations, (c) referring to any proceeding for any offense committed or alleged to have been committed by such individual, the disposal of such proceedings, or the sentence of any court in such proceedings, and (d) issued by government agencies peculiar to an individual which includes, but not limited to, social security numbers and licenses<br/>I/we understand, further, that Loan Star Lending Group Corp., shall keep the Personal Data and Information and the business and/or transaction/s that I/we do with LSLGC (the &ldquo;Business&rdquo;) in strict confidence, and that the collection and processing of all Personal Data and/or Information by LSLGC may be used for any of the following purposes (collectively, the &ldquo;Purposes&rdquo;):<br/>a. to make decisions relating to the establishment, maintenance or termination of accounts and the establishment, provision or continuation of banking/credit facilities or financial products and/or services including, but not limited to, lending, loan, mortgage and/or other secured transactions.<br/>b. to provide, operate, process and administer LSLGC accounts and services or to process applications for LSLGC accounts, products and/or services, and to maintain service quality and train staff;<br/>c. to undertake activities related to the provision of the LSLGC accounts and services including but not limited to transaction authorization, statement printing and distribution, customer service and conduct of surveys, the provision of research reports, offering documents, product profiles, customer profiling, term sheets or other product related materials, administration of rewards and loyalty programs;<br/>d. to provide product related services and support, including, without limitation, provision of processing or administrative support or acting as an intermediary / nominee shareholder / agent / broker / market participant / counterparty in connection with participation in various products (whether such products are offered by LSLGC;<br/>e. to verify the identity or authority of my/our family members, friends, beneficiaries, attorneys, attorneys-in-fact, shareholders, beneficial owners (if relevant), persons under any partners, committee members, directors, officers or authorized signatories, sureties, guarantors, other security and other individuals, representatives who contact LSLGC or may be contacted by LSLGC;<br/>f. for risk assessment, statistical and trend analysis and planning purposes, including to carry out data processing, credit, risk and anti-money laundering and sanctions analyses, creating and maintaining credit scoring models, and otherwise ensuring potential or ongoing credit worthiness of Data Subjects and Related Person/s, including conducting banking, credit, financial and other background checks and reviews, and maintaining banking, credit and financial history of individuals and the company for present and future reference;<br/>g. to monitor and record calls and electronic communications with Data Subject/s and Related Person/s for record keeping, quality assurance, customer service, training, investigation, litigation and fraud prevention purposes;<br/>h. for crime and fraud detection, prevention, investigation and prosecution;<br/>i. to enforce (including without limitation collecting amounts outstanding) or defend the rights of LSLGC and/or any of its affiliates and subsidiaries, its employees, officers and directors, contractual or otherwise;<br/>j. to perform internal management and management reporting, to operate control and management information systems, and to carry out business risk, control or compliance review or testing, internal audits or enable the conduct of external audits;<br/>k. for marketing to me/us and to individuals with similar profiles, attributes or behavior, financial, credit, investment, loan, mortgage, and other related products or services, conducting market, product and service research, and refining any products or services including by conducting data analysis, and surveys, by various modes of communication including mail, telephone call, SMS, electronic mail, internet, mobile, social media, chat and other technological tools and development;</td>
<td>l. to comply with any obligations, requirements, policies, procedures, measures or arrangements for sharing data and information within LSLGC and prevention or detection of money laundering, terrorist financing or other unlawful activities; and,<br/>m. any other transactions and/or purposes analogous or relating directly thereto.<br/>At the same time, I/we agree that the Information shall be retained by LSLGC for as long as necessary for the fulfillment of any of the aforementioned Purposes, and shall continue to be retained for a period of two (5) years notwithstanding the termination of any of the above Purposes.<br/>Further, I/we understand that, with respect to my/our submission, collection and processing of the Personal Data of Related Person/s, it is my/our duty and responsibility:<br/>(i) to inform said Related Person/s of the Purpose/s for which his/their Personal Data have been submitted, collected and processed by LSLGC,<br/>(ii) to obtain consent from the said Related Person/s for the collection and processing of his/their Personal Data/Information in accordance with the Data Privacy Act of 2012, and<br/>(iii) to inform LSLGC that such consent from said Related Person/s have been obtained.<br/>I/we hereby acknowledge that I/we have been provided with the written notification below on my/our rights as a Data Subject (each, a &ldquo;Right&rdquo;, collectively, the &ldquo;Rights&rdquo;) in accordance with the Data Privacy Act of 2012, to wit:<br/>i. to be informed whether Information and/or Personal Data is being or has been processed.<br/>ii. to require LSLGC to correct any Information and/or Personal Data relating to the Data Subject which is inaccurate;<br/>iii. to object to the processing of the Information and/or Personal Data in case of changes or amendments to the Information and/or Personal Data supplied or declared to the Data Subject;<br/>iv. to access the Information and/or Personal Data;<br/>v. to suspend, withdraw or order the blocking, removal or destruction of the Data Subject's Personal Data from LSLGC's information database system.<br/>I/we acknowledge, further, that if I/we was/were to exercise any of the Rights enumerated above, LSLGC reserves its right to re-evaluate and/or terminate its Business with me/us as well as any of the Purposes and/or LSLGC services/products for which the Information and/or Personal Data has been collected and processed.<br/>I/We have read and understood the above and hereby consent to, agree on, accept and acknowledge these terms of consent for myself/ourselves and/or as agent/s for and on behalf of the principal/s I/we represent by signing below<br/>Signed in Makati City on _________________, 20______ .<br/><span data-if="isCorporateBorrower">{{borrowerName}}<br/>Represented by:<br/><br/>{{borrowerRepresentative}}<br/>Authorized Signatory</span><span data-unless="isCorporateBorrower">{{borrowerName}}<br/>Signature Over Printed Name</span><span data-if="coBorrowerName"><br/><br/>{{coBorrowerName}}<br/>Signature Over Printed Name</span></td>
</tr>
</tbody></table>
</div>$consent$::text AS body
)
UPDATE public.document_template_versions v SET status = 'archived'
  FROM public.document_templates t, reviewed_body b
 WHERE v.template_id = t.id
   AND t.slug = 'consent_form'
   AND v.status = 'published'
   AND v.body IS DISTINCT FROM b.body;

WITH reviewed_body AS (
